// Private Phase A presentation only. Never used as the product SearchProvider.
const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,searchTimer,selectedStop=1,composing=false,originFocus,searchGeneration=0,departureScroll=null;
let entry=history.state??{key:crypto.randomUUID(),scroll:0};history.replaceState(entry,'');history.scrollRestoration='manual';
const qs=()=>new URL(location.href).searchParams;
const routeUrl=r=>'/routes/'+r.id;const artistUrl='/artists/10000000-0000-4000-8000-000000000001';
const currentRoute=()=>data.routes.find(r=>location.pathname===routeUrl(r))??data.route;
const placeUrl=id=>'/places/'+id;const back=`<a class="back" href="/" data-back aria-label="返回">←</a>`;
const action=(name,label)=>`<button class="text-action" data-action="${name}">${label}</button>`;
const row=(href,title,meta='',number='',extra='')=>`<a class="rule-row" href="${esc(href)}" ${extra}>${number?`<span class="number">${number}</span>`:''}<span class="row-label">${esc(title)}${meta?`<span class="row-meta">${esc(meta)}</span>`:''}</span><span class="arrow" aria-hidden="true">↗</span></a>`;
const blank=(label,title)=>`<div class="state"><h2>${label}</h2><p>${title}</p></div>`;
function save(){entry={...entry,scroll:scrollY};history.replaceState(entry,'');}
function go(url){entry={...entry,scroll:departureScroll??scrollY};departureScroll=null;history.replaceState(entry,'');if(sheet.open)sheet.close();entry={key:crypto.randomUUID(),scroll:0,from:location.pathname+location.search};history.pushState(entry,'',url);render();window.scrollTo(0,0);}
document.addEventListener('pointerdown',e=>{const link=e.target.closest('a[href^="/"],button[data-query]');departureScroll=link&&!link.hasAttribute('data-back')?scrollY:null;});
function returnBack(){if(entry.from){history.back();}else go('/search?q='+encodeURIComponent('台北'));}
addEventListener('popstate',()=>{entry=history.state??{key:'direct',scroll:0};if(sheet.open)sheet.close();render();requestAnimationFrame(()=>window.scrollTo(0,entry.scroll??0));});
addEventListener('pagehide',save);
function openSheet(title,content){if(!sheet.open)originFocus=document.activeElement;sheet.innerHTML=`<div class="sheet-head"><h2 id="sheet-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div>${content}`;if(!sheet.open)sheet.showModal();sheet.querySelector('button')?.focus();}
sheet.addEventListener('close',()=>{if(originFocus?.isConnected)originFocus.focus();});
sheet.addEventListener('click',e=>{if(e.target===sheet){const b=sheet.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)sheet.close();}});
function source(){const s=data.route.sources[0];openSheet('SOURCE',`<p>${esc(s.title)}</p><p class="sheet-detail">来源不可用 · 此处是合成测试来源，不能证明真实艺人到访。</p><div class="sheet-actions"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开来源 ↗</a>${action('verification','VERIFICATION ↗')}</div>`);}
function verification(){openSheet('VERIFICATION',`<p>Place：首站地点字段为 verified；其余站点为 unverified。</p><p>ArtistPlaceRelation：unverified；这是关联可信度。</p><p>Claim：无已核验主张。Source：unavailable。</p><p class="sheet-detail">Route 为合成已发布读模型。发布状态并不表示地点、关联或主张都已核验。</p>`);}
function stopPreview(n){selectedStop=n;syncMarkers();const s=currentRoute().stops[n-1];openSheet(`${String(n).padStart(2,'0')} · ${s.name}`,`<p class="eyebrow">${esc(data.hub.identity.canonicalName)} · 年份未收录</p><p>合成线索用于布局验证；不声称艺人真实到访。</p><div class="sheet-actions">${action('source','SOURCE ↗')}<a href="${placeUrl(s.placeId)}">PLACE ↗</a>${action('show-map','MAP ↓')}</div>`);}
function syncMarkers(){document.querySelectorAll('[data-stop],[data-marker]').forEach(el=>{const n=Number(el.dataset.stop??el.dataset.marker);el.classList.toggle('active',n===selectedStop);el.setAttribute('aria-pressed',String(n===selectedStop));});const status=document.querySelector('#map-status');if(status)status.textContent=`已选 ${String(selectedStop).padStart(2,'0')} · ${currentRoute().stops[selectedStop-1].name}；距离与时长暂无数据`;}
function home(){app.innerHTML=`<main class="page home"><p class="brand">START</p><div class="start-prompt"><h1>Start with</h1><form data-search><input type="search" maxlength="120" autocomplete="off" aria-label="想从什么开始" placeholder="艺人 / 城市 / 地点" aria-describedby="home-hint"></form><span class="question">?</span><div class="suggestion-list" hidden></div><span class="muted" id="home-hint">输入后按回车搜索</span></div><div class="suggestions"><button class="bubble" data-href="/artists/10000000-0000-4000-8000-000000000001">苏打绿 ↗</button><button class="bubble" data-href="/routes/10000000-0000-4000-8000-000000000070">春日城市路线 ↗</button><button class="bubble" data-href="/places/10000000-0000-4000-8000-000000000020">从一家书店开始 ↗</button></div><button class="doll" data-action="doll" aria-label="Doll 占位，低频轻互动待后续实现">DOLL<br>比例占位</button></main><nav class="nav" aria-label="主导航"><a href="/" aria-current="page">Start</a><button data-action="deferred-nav">Community</button><button data-action="deferred-nav">Me</button></nav>`;
 const input=app.querySelector('input'),page=app.querySelector('.home'),list=app.querySelector('.suggestion-list');
 const suggest=()=>{const q=input.value.trim();list.hidden=!q;list.innerHTML=q?['苏打绿','台北','春日书店'].filter(x=>x.includes(q)||q.toLowerCase()==='sodagreen').slice(0,5).map(x=>`<button type="button" data-query="${esc(x)}">${esc(x)} ↗</button>`).join(''):'';};
 input.addEventListener('focus',()=>page.classList.add('focused'));input.addEventListener('blur',()=>setTimeout(()=>{if(!page.contains(document.activeElement)){page.classList.remove('focused');list.hidden=true;}},100));input.addEventListener('input',suggest);input.addEventListener('compositionstart',()=>composing=true);input.addEventListener('compositionend',()=>{composing=false;suggest();});
}
function search(){const q=qs().get('q')??'';app.innerHTML=`<main class="page search"><header class="search-header">${back}<form data-search><input type="search" aria-label="搜索艺人、城市、地点" maxlength="120" value="${esc(q)}" placeholder="艺人 / 城市 / 地点"></form></header><div class="results" aria-live="polite"></div></main>`;loadResults(q);}
function loadResults(q){clearTimeout(searchTimer);const generation=++searchGeneration;const target=app.querySelector('.results');const scenario=qs().get('state');target.innerHTML=`<div class="state" role="status"><p>正在查找…</p><div class="skeleton"></div><div class="skeleton"></div></div>`;if(scenario==='loading')return;searchTimer=setTimeout(()=>{if(generation!==searchGeneration||!target.isConnected)return;if(scenario==='error'){target.innerHTML=`<div class="state"><h2>暂时无法搜索</h2><p>请稍后重试。原型模拟连接错误。</p>${action('retry','重试 ↻')}</div>`;return;}const key=q.trim().toLowerCase();let mode=key.includes('苏打绿')||key==='蘇打綠'||key==='sodagreen'?'artist':key.includes('台北')?'city':key.includes('南京')?'nanjing':key.includes('春日')?'place':key.includes('现场')?'event':!key?'default':'empty';if(scenario==='empty')mode='empty';
 if(mode==='empty'){target.innerHTML=blank('没有找到','试试艺人名字、城市或地点；不会自动进入固定路线。');return;}
 const sections=data.search.sections.map(s=>({...s,items:s.items.filter(item=>mode==='nanjing'?(s.type==='artist'||item.city.id===data.hub.footprintCities[1].city.id):mode==='place'?s.type==='place'&&item.name.includes('春日'):mode==='event'?s.type==='event':mode==='city'?(s.type==='artist'||item.city.id===data.hub.footprintCities[0].city.id):true)}));
 target.innerHTML=sections.map(s=>`<section class="section"><h2>${({artist:'ARTIST',route:'ROUTE',place:'PLACE',event:'EVENT'})[s.type]}</h2>${s.items.length?s.items.map((i,n)=>s.type==='artist'?row(artistUrl,i.canonicalName,i.footprintCities.map(c=>c.city.name).join(' / ')):s.type==='route'?row(routeUrl(i),i.title,`${i.artist.canonicalName} · ${i.city.name}`,String(n+1).padStart(2,'0')):s.type==='place'?row(placeUrl(i.id),'• '+i.name,i.city.name):`<button class="rule-row" data-action="event"><span class="event-date">12 / 01</span><span class="row-label">${esc(i.title)}<span class="row-meta">LIVE · ${esc(i.city.name)} · 已取消（测试）</span></span><span class="arrow">↗</span></button>`).join(''):'<p class="muted">暂无匹配内容</p>'}</section>`).join('');requestAnimationFrame(()=>window.scrollTo(0,entry.scroll??0));},240);}
function artist(){const cityLabels=[...data.hub.footprintCities.map(c=>c.city.name),...data.presentation.extraCityLabels];app.innerHTML=`<main class="page artist">${back}<header class="identity"><h1>${esc(data.hub.identity.canonicalName)}</h1><p class="eyebrow">ARTIST / CITY BOOKLET</p></header><div class="artist-layout"><nav class="city-index" aria-label="城市索引">${cityLabels.map((c,i)=>`<a href="#city-${i}" data-city="${i}" ${i===0?'aria-current="true"':''}>${esc(c)}</a>`).join('')}</nav><div class="chapters">${cityLabels.map((c,i)=>`<section class="chapter" id="city-${i}"><h2><small>${String(i+1).padStart(2,'0')}</small>${esc(c)}</h2>${i<2?data.hub.recommendedRoutes.filter(r=>r.city.name===c).map((r,n)=>row(routeUrl(r),r.title,'',String(n+1).padStart(2,'0'))).join(''):'<p class="chapter-empty">暂无可公开推荐路线</p><p class="chapter-empty"><small>布局压力示例，不表示真实艺人足迹</small></p>'}${i===0?`<div style="margin-top:28px"><h3 class="eyebrow">OPTIONAL EVENT</h3><button class="rule-row" data-action="event"><span class="row-label">${esc(data.event.title)}<span class="row-meta">12 / 01 · 已取消（测试）</span></span><span class="arrow">↗</span></button></div>`:''}</section>`).join('')}</div></div></main>`;
 requestAnimationFrame(syncCity);}
function syncCity(){const chapters=[...app.querySelectorAll('.chapter')];if(!chapters.length)return;let active=0;chapters.forEach((el,i)=>{if(el.getBoundingClientRect().top<=80)active=i;});activateCity(active);}
addEventListener('scroll',()=>requestAnimationFrame(syncCity),{passive:true});
function activateCity(i){app.querySelectorAll('[data-city]').forEach(a=>{if(a.dataset.city===String(i)){a.setAttribute('aria-current','true');if(innerWidth<768){const nav=a.parentElement;nav.scrollTo({left:a.offsetLeft-nav.offsetLeft-16,behavior:'auto'});}}else a.removeAttribute('aria-current');});}
function route(){const r=currentRoute();if(selectedStop>r.stops.length)selectedStop=1;app.innerHTML=`<main class="page route">${back}<header class="identity"><p class="eyebrow">${esc(r.artist.canonicalName)} / ${esc(r.city.name)}</p><h1>${esc(r.title)}</h1></header><div class="actions">${action('start','START →')}${action('share','SHARE ↗')}</div><div class="route-layout"><section class="stops"><div class="section-label"><h2>ROUTE</h2><button class="text-action" data-action="map">MAP ↓</button></div>${r.stops.map(s=>`<button class="rule-row stop-row ${s.sequence===selectedStop?'active':''}" data-stop="${s.sequence}" aria-pressed="${s.sequence===selectedStop}"><span class="number">${String(s.sequence).padStart(2,'0')}</span><span class="row-label">${esc(s.name)}</span><span class="arrow">↗</span></button>`).join('')}</section><section class="map-panel" id="map"><div class="section-label"><h2>MAP</h2><span class="muted">示意，不能导航</span></div><div class="map-frame" aria-label="站点关系示意图，非真实地图"><div class="trace" aria-hidden="true"></div>${r.stops.map((s,i)=>`<button class="marker ${s.sequence===selectedStop?'active':''}" data-marker="${s.sequence}" aria-pressed="${s.sequence===selectedStop}" aria-label="地图站点 ${s.sequence} ${esc(s.name)}" style="left:${[15,62,56,27,63][i]}%;top:${[25,14,42,60,70][i]}%">${String(s.sequence).padStart(2,'0')}</button>`).join('')}<span class="map-caption">PRIVATE LAYOUT TRACE</span></div><p class="map-status" id="map-status" role="status"></p></section><div class="bottom-start">${action('start','START →')}</div></div></main>`;syncMarkers();}
function place(){const p=data.places.find(p=>location.pathname.endsWith(p.identity.id));if(!p){app.innerHTML=`<main class="page">${back}${blank('地点不存在','该链接没有对应的合成读模型。')}</main>`;return;}app.innerHTML=`<main class="page place">${back}<header class="identity"><h1>${esc(p.identity.name)}</h1><p class="eyebrow">${esc(p.identity.city.name)}</p><p class="muted">${esc(p.relatedArtists[0].canonicalName)} / 年份未收录</p></header><div class="place-layout"><section class="why"><h2>WHY HERE</h2><p>${esc(p.artistRelations[0].explanation)}</p>${action('source','SOURCE ↗')}</section><section class="here"><h2>HERE</h2><div class="mini-grid"><div class="mini-info"><h3>PHOTO SPOT</h3><p>暂未收录</p></div><div class="mini-info"><h3>ANGLE</h3><p>暂未收录</p></div></div><button class="address" data-action="address"><strong>ADDRESS ↗</strong><span>${esc(p.address??'地址暂未收录')}</span></button><p class="notice">营业时间 / 到访提示暂未收录</p></section><section class="section reference"><div class="section-label"><h2>REFERENCE</h2><span class="muted">无已授权媒体</span></div><div class="image-slot">图片结构占位 · 不引用真实人物素材</div><p class="notice">Photo Spot / Angle / Reference 等待真实资料。</p></section><section class="related"><h2>RELATED</h2>${row(routeUrl(p.relatedRoutes[0]),p.relatedRoutes[0].title)}${row(artistUrl,p.relatedArtists[0].canonicalName)}</section></div></main>`;}
function render(){clearTimeout(searchTimer);searchGeneration++;document.title='START · Phase A 灰阶原型';if(location.pathname==='/')home();else if(location.pathname==='/search')search();else if(location.pathname.startsWith('/artists/')){if(location.pathname!==artistUrl){app.innerHTML=`<main class="page">${back}${blank('艺人不存在','原型仅包含指定合成读模型。')}</main>`;}else artist();}else if(location.pathname.startsWith('/routes/')){if(!data.hub.recommendedRoutes.some(r=>location.pathname===routeUrl(r)))app.innerHTML=`<main class="page">${back}${blank('路线不存在','原型没有此路线。')}</main>`;else route();}else if(location.pathname.startsWith('/places/'))place();else app.innerHTML=`<main class="page">${back}${blank('页面不存在','')}</main>`;}
document.addEventListener('submit',e=>{if(e.target.matches('[data-search]')){e.preventDefault();if(composing)return;const q=e.target.querySelector('input').value.trim();go('/search?q='+encodeURIComponent(q));}});
document.addEventListener('click',async e=>{const target=e.target.closest('a,button');if(!target)return;if(target.matches('[data-back]')){e.preventDefault();returnBack();return;}if(target.dataset.city!==undefined){e.preventDefault();activateCity(target.dataset.city);document.querySelector('#city-'+target.dataset.city)?.scrollIntoView();return;}if(target.dataset.href){go(target.dataset.href);return;}if(target.dataset.query){go('/search?q='+encodeURIComponent(target.dataset.query));return;}if(target.dataset.stop){stopPreview(Number(target.dataset.stop));return;}if(target.dataset.marker){selectedStop=Number(target.dataset.marker);syncMarkers();return;}if(target.tagName==='A'&&target.getAttribute('href')?.startsWith('/')){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();go(target.getAttribute('href'));return;}switch(target.dataset.action){case'close':sheet.close();break;case'source':source();break;case'verification':verification();break;case'map':document.querySelector('#map')?.scrollIntoView();break;case'show-map':sheet.close();document.querySelector('#map')?.scrollIntoView();break;case'start':openSheet('开始路线 · Slice 003',`<p>Journey 尚未实现。本轮只验证 Discovery 结构。</p><p class="sheet-detail">不会创建行程、定位到达或完成记录。</p>`);break;case'share':try{await navigator.clipboard.writeText(location.href);openSheet('分享给朋友',`<p>已复制此本地原型链接。需要在本机启动原型才能访问。</p>`);}catch{openSheet('分享给朋友',`<p>请复制浏览器地址：</p><p class="sheet-detail">${esc(location.href)}</p>`);}break;case'address':openSheet('ADDRESS',`<p>${esc(data.places.find(p=>location.pathname.endsWith(p.identity.id))?.address)}</p><p class="sheet-detail">测试地址，未接地图 Provider，不执行真实导航。</p>`);break;case'event':openSheet('EVENT · 最小读目标',`<p>${esc(data.event.title)}</p><p>12 / 01 · 台北 · 已取消（测试）</p><p class="sheet-detail">合成 Event read 模型；不是 Event Hub，不提供报名。</p>`);break;case'retry':{const url=new URL(location.href);url.searchParams.delete('state');history.replaceState(entry,'',url);loadResults(qs().get('q')??'');break;}case'deferred-nav':openSheet('后续切片',`<p>本轮仅包含 Discovery 五页灰阶结构。</p>`);break;case'doll':openSheet('DOLL · 比例占位',`<p>不加载、不重绘锁定角色素材。低频轻互动待后续切片。</p>`);break;}});
try{const response=await fetch('/fixture.json');if(!response.ok)throw Error('fixture unavailable');data=await response.json();render();}catch{app.innerHTML='<main class="boot-error"><h1>原型资料加载失败</h1><p>请运行 build-fixture.mjs，随后刷新。</p><button class="text-action" onclick="location.reload()">重新加载 ↻</button></main>';}
